bounded_host_request.command:
set -eu
test "$(docker inspect gace-createvdobot-videobot-poll-1 --format '{{.State.Running}}')" = true
docker exec -i gace-createvdobot-videobot-poll-1 node --input-type=module <<'NODE'
import fs from 'node:fs';
import pg from 'pg';
const db=new pg.Pool({host:process.env.VIDEOBOT_DB_HOST,user:process.env.VIDEOBOT_DB_USER,database:process.env.VIDEOBOT_DB_NAME,password:fs.readFileSync('/run/secrets/videobot_db_password','utf8').trim(),max:1});
try{
const q=await db.query("SELECT COUNT(*)::int AS total, COUNT(*) FILTER(WHERE status='sent')::int AS sent FROM videobot_post_receipts");
const p=await db.query("SELECT COUNT(DISTINCT delivery_key)::int AS paid FROM videobot_stars_ledger WHERE kind='paid'");
if(q.rows[0].sent===1&&p.rows[0].paid===1)process.exitCode=0;
else if(q.rows[0].sent>1&&p.rows[0].paid===1)process.exitCode=42;
else process.exitCode=43;
}finally{await db.end()}
NODE
